del.isLoading {                    Text("No results found")                        .foregroundColor(.secondary)                        .frame(maxWidth: .infinity, alignment: .center)                }            }            .listStyle(PlainListStyle())            .navigationTitle("Search Games")            .searchable(text: $viewModel.searchTerm, placement: .navigationBarDrawer(displayMode: .always))            .alert(isPresented: Binding<Bool>(                get: { viewModel.errorMessage != nil },                set: { _ in viewModel.errorMessage = nil }            )) {                Alert(title: Text("Error"),                      message: Text(viewModel.errorMessage ?? "Unknown error"),                      dismissButton: .default(Text("OK")))            }        }    }}